; Music streams, note tables and DPCM voices (generated by tools/convert_audio.py).
.export music_p1, music_p2, music_tri, music_noise, note_lo, note_hi
.export dpcm0, dpcm1, dpcm2, dpcm3, dpcm4, dpcm5, dpcm6, dpcm7
.segment "MUSIC"
music_p1:    .incbin "res/music_p1.bin"
music_p2:    .incbin "res/music_p2.bin"
music_tri:   .incbin "res/music_tri.bin"
music_noise: .incbin "res/music_noise.bin"
note_lo:     .incbin "res/note_lo.bin"
note_hi:     .incbin "res/note_hi.bin"
; DMC sample addresses must be 64-byte aligned and lie in $C000-$FFFF.
.segment "DMC"
dpcm0: .incbin "res/dpcm0.bin"
.align 64
dpcm1: .incbin "res/dpcm1.bin"
.align 64
dpcm2: .incbin "res/dpcm2.bin"
.align 64
dpcm3: .incbin "res/dpcm3.bin"
.align 64
dpcm4: .incbin "res/dpcm4.bin"
.align 64
dpcm5: .incbin "res/dpcm5.bin"
.align 64
dpcm6: .incbin "res/dpcm6.bin"
.align 64
dpcm7: .incbin "res/dpcm7.bin"
.align 64
